<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/functions.php';require_permission($pdo,'view_employees');$active='employees';$pageTitle='Employees';
$rows=$pdo->query("SELECT e.*,u.name,u.email,u.status user_status,r.name role_name FROM employees e JOIN users u ON u.id=e.user_id JOIN roles r ON r.id=u.role_id ORDER BY e.id DESC")->fetchAll();include __DIR__.'/../../includes/header.php';?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><span class="eyebrow">PEOPLE</span><h1 class="page-title">Employees</h1></div><?php if(has_permission($pdo,'manage_employees')):?><a href="form.php" class="btn btn-stare">Add Employee</a><?php endif;?></div>
<div class="panel"><div class="table-responsive"><table class="table stare-table align-middle"><thead><tr><th>Employee</th><th>Department</th><th>Position</th><th>Salary</th><th>Status</th><th>Role</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><div class="text-secondary small"><?=e($r['email'])?></div></td><td><?=e($r['department'])?></td><td><?=e($r['position'])?></td><td><?=money($r['salary'])?></td><td><?=status_badge($r['user_status'])?></td><td><?=e(ucfirst($r['role_name']))?></td><td><?php if(has_permission($pdo,'manage_employees')):?><a href="form.php?id=<?=$r['id']?>" class="action-link">Edit</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
